B.aPA=new A.a("\u0648\u0641\u064a \u063a\u062f\u0627\u0629 \u0627\u0644\u0641\u062a\u062d \u0628\u0644\u063a \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646 \u062e\u0632\u0627\u0639\u0629 \u062d\u0644\u0641\u0627\u0621\u0647 \u0639\u062f\u062a \u0639\u0644\u0649 \u0631\u062c\u0644 \u0645\u0646 \u0647\u0630\u064a\u0644 \u0641\u0642\u062a\u0644\u0648\u0647 \u0648\u0647\u0648 \u0645\u0634\u0631\u0643 \u0628\u0631\u062c\u0644 \u0642\u062a\u0644 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629\u060c \u0641\u063a\u0636\u0628 \u0648\u0642\u0627\u0645 \u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0633 \u062e\u0637\u064a\u0628\u0627\u064b \u0641\u0642\u0627\u0644: \u064a\u0627\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0625\u0646 \u0627\u0644\u0644\u0647 \u0642\u062f \u062d\u0631\u0645 \u0645\u0643\u0629 \u064a\u0648\u0645 \u062e\u0644\u0642 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0641\u0647\u064a \u062d\u0631\u0627\u0645 \u0628\u062d\u0631\u0645\u0629 \u0627\u0644\u0644\u0647 \u0627\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0641\u0644\u0627 \u064a\u062d\u0644 \u0644\u0623\u0645\u0631\u0626 \u064a\u0624\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631 \u0623\u0646 \u064a\u0633\u0641\u0643 \u0641\u064a\u0647\u0627 \u062f\u0645\u0627\u064b \u0648\u0644\u0627 \u064a\u0639\u0636\u062f -\u064a\u0642\u0637\u0639- \u0641\u064a\u0647\u0627 \u0634\u062c\u0631\u0627\u064b \u0644\u0645 \u0644\u0627 \u062a\u062d\u0644 \u0644\u0623\u062d\u062f \u0643\u0627\u0646 \u0642\u0628\u0644\u064a\u060c \u0648\u0644\u0627 \u062a\u062d\u0644 \u0644\u0623\u062d\u062f \u064a\u0643\u0648\u0646 \u0628\u0639\u062f\u064a \u0648\u0644\u0645 \u062a\u062d\u0644 \u0644\u064a \u0625\u0644\u0627 \u0647\u0630\u0647 \u0627\u0644\u0633\u0627\u0639\u0629 \u063a\u0636\u0628\u0627\u064b \u0639\u0644\u0649 \u0623\u0647\u0644\u0647\u0627\u060c \u062b\u0645 \u0642\u062f \u0631\u062c\u0639\u062a \u0643\u062d\u0631\u0645\u062a\u0647\u0627 \u0628\u0627\u0644\u0623\u0645\u0633 \u0641\u0644\u064a\u0628\u0644\u063a \u0627\u0644\u0634\u0627\u0647\u062f \u0645\u0646\u0643\u0645 \u0627\u0644\u063a\u0627\u0626\u0628\u060c \u0641\u0645\u0646 \u0642\u0627\u0644 \u0644\u0643\u0645 \u0625\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u062f \u0642\u0627\u062a\u0644 \u0641\u064a\u0647\u0627 \u0641\u0642\u0648\u0644\u0648\u0627: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0642\u062f \u0623\u062d\u0644\u0651\u0647\u0627 \u0644\u0631\u0633\u0648\u0644\u0647 \u0648\u0644\u0645 \u064a\u062d\u0644\u0647\u0627 \u0644\u0643\u0645\u060c \u064a\u0627\u0645\u0639\u0634\u0631 \u062e\u0632\u0627\u0639\u0629: \u0627\u0631\u0641\u0639\u0648\u0627 \u0623\u064a\u062f\u064a\u0643\u0645 \u0639\u0646 \u0627\u0644\u0642\u062a\u0644 \u0641\u0644\u0642\u062f \u0643\u062b\u0631 \u0625\u0646 \u0646\u0641\u0639\u060c \u0644\u0642\u062f \u0642\u062a\u0644\u062a\u0645 \u0642\u062a\u064a\u0644\u0627\u064b \u0644\u0623\u062f\u064a\u0646\u0651\u064e\u0647 \u0641\u0645\u0646 \u0642\u062a\u0644 \u0628\u0639\u062f \u0645\u0642\u0627\u0645\u064a \u0647\u0630\u0627 \u0641\u0623\u0647\u0644\u0647 \u0628\u062e\u064a\u0631 \u0627\u0644\u0646\u0638\u0631\u064a\u0646\u060c \u0625\u0646 \u0634\u0627\u0624\u0648\u0627 \u0642\u064f\u062f\u0651\u0650\u0645 \u0642\u0627\u062a\u0644\u0647 \u0648\u0625\u0646 \u0634\u0627\u0624\u0648\u0627 \u0641\u0639\u0642\u0644\u0647.",null)
