B.aKT=new A.a("\u0645\u0646\u0627\u0629 \u0623\u0633\u0645 \u0635\u0646\u0645 \u0643\u0627\u0646\u062a \u0639\u0644\u0649 \u0633\u0627\u062d\u0644 \u0627\u0644\u0628\u062d\u0631 \u0627\u0644\u0623\u062d\u0645\u0631 \u0645\u0645\u0627 \u064a\u0644\u064a \u0642\u062f\u064a\u062f\u0627\u064b -\u0645\u0627\u0628\u064a\u0646 \u0645\u0643\u0629 \u0648\u0627\u0644\u0645\u062f\u064a\u0646\u0629- \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u062a\u0639\u0631\u0641 \u0628\u0627\u0644\u0645\u0634\u0644\u0644 \u0648\u0643\u0627\u0646\u062a \u0644\u0644\u0623\u0648\u0633 \u0648\u0627\u0644\u062e\u0632\u0631\u062c \u0648\u063a\u0633\u0627\u0646 \u0648\u0645\u0646 \u062f\u0627\u0646 \u0628\u062f\u064a\u0646\u0647\u0645 \u064a\u0639\u0628\u062f\u0648\u0646\u0647\u0627 \u0648\u064a\u0639\u0638\u0645\u0648\u0646\u0647\u0627 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0648\u064a\u0647\u0644\u0648\u0646 \u0645\u0646\u0647\u0627 \u0644\u0644\u062d\u062c\u060c \u0648\u0642\u062f \u0628\u0644\u063a \u0645\u0646 \u062a\u0639\u0638\u064a\u0645\u0647\u0645 \u0625\u064a\u0627\u0647\u0627 \u0623\u0646\u0647\u0645 \u0643\u0627\u0646\u0648\u0627 \u0644\u0627\u064a\u0637\u0648\u0641\u0648\u0646 \u0628\u064a\u0646 \u0627\u0644\u0635\u0641\u0627 \u0648\u0627\u0644\u0645\u0631\u0648\u0629 \u062a\u062d\u0631\u062c\u0627\u064b \u0648\u062a\u0639\u0638\u064a\u0645\u0627\u064b \u0644\u0647\u0627 \u062d\u064a\u062b \u0643\u0627\u0646 \u0630\u0644\u0643 \u0633\u0646\u0629 \u0641\u064a \u0622\u0628\u0627\u0626\u0647\u0645 \u0645\u0646 \u0622\u062d\u0631\u0645 \u0644\u0645\u0646\u0627\u0629 \u0644\u0645 \u064a\u0637\u0641 \u0628\u064a\u0646 \u0627\u0644\u0635\u0641\u0627 \u0648\u0627\u0644\u0645\u0631\u0648\u0629 \u0648\u0644\u0645 \u062a\u0632\u0644 \u0647\u0630\u0647 \u0639\u0627\u062f\u062a\u0647\u0645 \u062d\u062a\u0649 \u0623\u0633\u0644\u0645\u0648\u0627 \u0641\u0644\u0645\u0627 \u0642\u062f\u0645\u0648\u0627 \u0645\u0639 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0644\u062d\u062c \u0630\u0643\u0631\u0648\u0627 \u0630\u0644\u0643 \u0644\u0647 \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0635\u0651\u064e\u0641\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0648\u064e\u0629\u064e \u0645\u0650\u0646\u0652 \u0634\u064e\u0639\u064e\u0627\u0626\u0650\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0645\u064e\u0646\u0652 \u062d\u064e\u062c\u0651\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0623\u064e\u0648\u0650 \u0627\u0639\u0652\u062a\u064e\u0645\u064e\u0631\u064e \u0641\u064e\u0644\u0627 \u062c\u064f\u0646\u064e\u0627\u062d\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0646\u0652 \u064a\u064e\u0637\u0651\u064e\u0648\u0651\u064e\u0641\u064e \u0628\u0650\u0647\u0650\u0645\u064e\u0627 \u0648\u064e\u0645\u064e\u0646\u0652 \u062a\u064e\u0637\u064e\u0648\u0651\u064e\u0639\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u0627\u0643\u0650\u0631\u064c \u0639\u064e\u0644\u0650\u064a\u0645\u064c - \u0633\u0648\u0631\u0629 \u0627\u0644\u0628\u0642\u0631\u0629",null)
B.auX=new A.a("\u0648\u0642\u062f \u0643\u0627\u0646 \u0623\u0648\u0644 \u0645\u0646 \u0646\u0635\u0628\u0647\u0627 \u0644\u0647\u0645 \u0645\u0624\u0633\u0633 \u0627\u0644\u0634\u0631\u0643 \u0641\u064a \u0627\u0644\u062c\u0632\u064a\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0645\u0628\u062a\u062f\u0639 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0645\u062d\u0631\u0641 \u0627\u0644\u062d\u0646\u0641\u064a\u0629 \u062f\u064a\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0644\u062d\u064a \u0627\u0644\u062e\u0632\u0627\u0639\u064a\u060c \u0641\u0644\u0645\u0627 \u0641\u062a\u062d \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0645\u0643\u0629 \u0628\u0639\u062b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0649 \u0645\u0646\u0627\u0629 \u0631\u062c\u0644\u0627\u064b \u0645\u0646 \u0623\u0647\u0644\u0647\u0627 \u0633\u0627\u0628\u0642\u0627\u064b \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0638\u0645\u0648\u0646\u0647\u0627 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0648\u0647\u0648 \u0633\u0639\u062f \u0628\u0646 \u0632\u064a\u062f \u0627\u0644\u0623\u0634\u0647\u0644\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0639\u0644\u0649 \u0631\u0623\u0633 \u0633\u0631\u064a\u0629 \u0642\u0648\u062a\u0647\u0627 \u0639\u0634\u0631\u0648\u0646 \u0641\u0627\u0631\u0633\u0627\u064b \u0648\u0643\u0627\u0646 \u0648\u0627\u062c\u0628 \u0627\u0644\u0633\u0631\u064a\u0629 \u0647\u0648 \u0625\u0632\u0627\u0644\u0629 \u0645\u0646\u0627\u0629 \u0645\u0646 \u0627\u0644\u0648\u062c\u0648\u062f \u0646\u0647\u0627\u0626\u064a\u0627\u064b.",null)
B.aSP=new A.a("\u0627\u0646\u0637\u0644\u0642 \u0632\u064a\u062f \u0648\u0645\u0646 \u0645\u0639\u0647 \u0641\u064a \u0645\u0633\u064a\u0631 \u0627\u0642\u062a\u0631\u0627\u0628\u064a \u0633\u0631\u064a\u0639 \u0644\u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u0645\u0647\u0645\u0629 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u062d\u062a\u0649 \u0648\u0635\u0644 \u0625\u0644\u064a\u0647\u0627 \u0641\u0642\u0627\u0628\u0644\u0647 \u0633\u0627\u062f\u0646\u0647\u0627 \u0645\u062a\u0633\u0627\u0626\u0644\u0627\u064b: \u0645\u0627\u062a\u0631\u064a\u062f \u0642\u0627\u0644: \u0647\u062f\u0645 \u0645\u0646\u0627\u0629\u060c \u0642\u0627\u0644: \u0623\u0646\u062a \u0648\u0630\u0627\u0643\u060c \u0641\u0623\u0642\u0628\u0644 \u0633\u0639\u062f \u064a\u0645\u0634\u064a \u0625\u0644\u064a\u0647\u0627\u060c \u0648\u062a\u062e\u0631\u062c \u0625\u0644\u064a\u0647 \u0627\u0645\u0631\u0623\u0629 \u0639\u0631\u064a\u0627\u0646\u0629 \u0633\u0648\u062f\u0627\u0621 \u062b\u0627\u0626\u0631\u0629 \u0627\u0644\u0631\u0623\u0633 \u062a\u062f\u0639\u0648 \u0628\u0627\u0644\u0648\u064a\u0644 \u0648\u062a\u0636\u0631\u0628 \u0635\u062f\u0631\u0647\u0627. \u0641\u0635\u0627\u062d \u0628\u0647\u0627 \u0627\u0644\u0633\u0627\u062f\u0646 \u0635\u064a\u062d\u0629 \u0627\u0644\u0648\u0627\u062b\u0642: \u0645\u0646\u0627\u0629 \u062f\u0648\u0646\u0643 \u0628\u0639\u0636 \u0639\u0635\u0627\u062a\u0643 \u0648\u0644\u0643\u0646 \u0635\u064a\u062d\u062a\u0647 \u0630\u0647\u0628\u062a \u0623\u062f\u0631\u0627\u062c \u0627\u0644\u0631\u064a\u0627\u062d\u060c \u0641\u0644\u0645 \u064a\u0623\u0628\u0647 \u0633\u0639\u062f \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0628\u0643\u0644 \u0630\u0644\u0643 \u0648\u0636\u0631\u0628\u0647\u0627 \u0636\u0631\u0628\u0629 \u0642\u0627\u062a\u0644\u0629 \u0642\u0636\u062a \u0639\u0644\u064a\u0647\u0627 \u062b\u0645 \u0623\u0642\u0628\u0644 \u0645\u0639 \u0623\u0635\u062d\u0627\u0628\u0647 \u0639\u0644\u0649 \u0627\u0644\u0635\u0646\u0645 \u0641\u0647\u062f\u0645\u0648\u0647 \u0648\u0644\u0645 \u064a\u062c\u062f\u0648\u0627 \u0641\u064a \u062e\u0632\u0627\u0646\u062a\u0647\u0627 \u0634\u064a\u0626\u0627\u064b\u060c \u0648\u0627\u0646\u0635\u0631\u0641 \u0631\u0627\u062c\u0639\u0627\u064b \u0627\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa .",null)
