B.aMN=new A.a("\u062b\u0645 \u0627\u063a\u062a\u062f\u064a\u0646\u0627 \u0631\u0627\u062c\u0639\u064a\u0646 \u0625\u0644\u0649 \u0628\u0644\u0627\u062f\u0646\u0627 \u0623\u0646\u0627 \u0648\u0635\u0648\u0627\u062d\u0628\u064a\u060c \u0641\u0631\u0643\u0628\u062a \u0623\u062a\u0627\u0646\u064a \u0627\u0644\u0642\u0645\u0631\u0627\u0621 \u0641\u062d\u0645\u0644\u062a\u0647 \u0645\u0639\u064a\u060c \u0641\u0648\u0627\u0644\u0630\u064a \u0646\u0641\u0633 \u062d\u0644\u064a\u0645\u0629 \u0628\u064a\u062f\u0647 \u0644\u0642\u0637\u0639\u062a \u0627\u0644\u0631\u0643\u0628 -\u0633\u0628\u0642\u062a \u0627\u0644\u0631\u0643\u0628- \u062d\u062a\u0649 \u0625\u0646 \u0627\u0644\u0646\u0633\u0648\u0629 \u0644\u064a\u0642\u0644\u0646: \u0623\u0645\u0633\u0643\u064a \u0639\u0644\u064a\u0646\u0627\u060c \u0623\u0647\u0630\u0647 \u0623\u062a\u0627\u0646\u0643 \u0627\u0644\u062a\u064a \u062e\u0631\u062c\u062a \u0639\u0644\u064a\u0647\u0627\u061f \u0641\u0642\u0644\u062a: \u0646\u0639\u0645\u060c \u0641\u0642\u0627\u0644\u0648\u0627: \u0625\u0646\u0647\u0627 \u0643\u0627\u0646\u062a \u0623\u062f\u0645\u062a \u062d\u064a\u0646 \u0623\u0642\u0628\u0644\u0646\u0627 \u0641\u0645\u0627 \u0634\u0623\u0646\u0647\u0627\u061f \u0642\u0627\u0644\u062a: \u0641\u0642\u0644\u062a: \u0648\u0627\u0644\u0644\u0647 \u062d\u0645\u0644\u062a \u0639\u0644\u064a\u0647\u0627 \u063a\u0644\u0627\u0645\u0627 \u0645\u0628\u0627\u0631\u0643\u0627.",null)
B.aQf=new A.a("\u0642\u0627\u0644\u062a: \u0641\u062e\u0631\u062c\u0646\u0627\u060c \u0641\u0645\u0627 \u0632\u0627\u0644 \u064a\u0632\u064a\u062f\u0646\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a \u0643\u0644 \u064a\u0648\u0645 \u062e\u064a\u0631\u064b\u0627\u060c \u062d\u062a\u0649 \u0642\u062f\u0645\u0646\u0627 \u0648\u0627\u0644\u0628\u0644\u0627\u062f \u0633\u0646\u0629\u060c \u0648\u0644\u0642\u062f \u0643\u0627\u0646 \u0631\u0639\u0627\u062a\u0646\u0627 \u064a\u0633\u0631\u062d\u0648\u0646 \u062b\u0645 \u064a\u0631\u0648\u062d\u0648\u0646\u060c \u0641\u062a\u0631\u0648\u062d \u0623\u063a\u0646\u0627\u0645 \u0628\u0646\u064a \u0633\u0639\u062f \u062c\u064a\u0627\u0639\u064b\u0627\u060c \u0648\u062a\u0631\u0648\u062d \u063a\u0646\u0645\u064a \u0628\u0637\u0627\u0646\u064b\u0627\u060c \u062d\u064f\u0641\u0651\u064e\u0644\u0627\u064b -\u0643\u062b\u064a\u0631\u0627\u062a \u0627\u0644\u0644\u0628\u0646- \u0641\u0646\u062d\u0644\u0628\u060c \u0648\u0646\u0634\u0631\u0628\u060c \u0641\u064a\u0642\u0648\u0644\u0648\u0646: \u0645\u0627 \u0634\u0623\u0646 \u063a\u0646\u0645 \u0627\u0644\u062d\u0627\u0631\u062b \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0639\u0632\u0649\u060c \u0648\u063a\u0646\u0645 \u062d\u0644\u064a\u0645\u0629 \u062a\u0631\u0648\u062d \u0634\u0628\u0627\u0639\u064b\u0627 \u062d\u064f\u0641\u0651\u064e\u0644\u0627\u064b\u060c \u0648\u062a\u0631\u0648\u062d \u063a\u0646\u0645\u0643\u0645 \u062c\u064a\u0627\u0639\u064b\u0627\u060c \u0648\u064a\u0644\u0643\u0645 \u0627\u0633\u0631\u062d\u0648\u0627 \u062d\u064a\u062b \u062a\u0633\u0631\u062d \u063a\u0646\u0645 \u0631\u0639\u0627\u0626\u0647\u0645\u060c \u0641\u064a\u0633\u0631\u062d\u0648\u0646 \u0645\u0639\u0647\u0645\u060c \u0641\u0645\u0627 \u062a\u0631\u0648\u062d \u0625\u0644\u0627 \u062c\u064a\u0627\u0639\u064b\u0627 \u0643\u0645\u0627 \u0643\u0627\u0646\u062a\u060c \u0648\u062a\u0631\u062c\u0639 \u063a\u0646\u0645\u064a \u0643\u0645\u0627 \u0643\u0627\u0646\u062a.",null)
B.aNA=new A.a("\u0642\u0627\u0644\u062a: \u0648\u0643\u0627\u0646 \u064a\u0634\u0628 \u0634\u0628\u0627\u0628\u064b\u0627 \u0645\u0627 \u064a\u0634\u0628\u0651\u064f\u0647 \u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u063a\u0644\u0645\u0627\u0646\u060c \u064a\u0634\u0628 \u0641\u064a \u0627\u0644\u064a\u0648\u0645 \u0634\u0628\u0627\u0628 \u0627\u0644\u0633\u0646\u0629\u060c \u0641\u0644\u0645\u0627 \u0627\u0633\u062a\u0643\u0645\u0644 \u0633\u0646\u062a\u064a\u0646 \u0623\u0642\u062f\u0645\u0646\u0627\u0647 \u0645\u0643\u0629\u060c \u0623\u0646\u0627 \u0648\u0623\u0628\u0648\u0647\u060c \u0641\u0642\u0644\u0646\u0627: \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u0646\u0641\u0627\u0631\u0642\u0647 \u0623\u0628\u062f\u064b\u0627 \u0648\u0646\u062d\u0646 \u0646\u0633\u062a\u0637\u064a\u0639\u060c \u0641\u0644\u0645\u0627 \u0623\u062a\u064a\u0646\u0627 \u0623\u0645\u0647\u060c \u0642\u0644\u0646\u0627: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0631\u0623\u064a\u0646\u0627 \u0635\u0628\u064a\u064b\u0627 \u0642\u0637 \u0623\u0639\u0638\u0645 \u0628\u0631\u0643\u0629 \u0645\u0646\u0647\u060c \u0648\u0625\u0646\u0627 \u0646\u062a\u062e\u0648\u0641 \u0639\u0644\u064a\u0647 \u0648\u0628\u0627\u0621 \u0645\u0643\u0629 \u0648\u0623\u0633\u0642\u0627\u0645\u0647\u0627\u060c \u0641\u062f\u0639\u064a\u0647 \u0646\u0631\u062c\u0639 \u0628\u0647 \u062d\u062a\u0649 \u062a\u0628\u0631\u0626\u064a \u0645\u0646 \u062f\u0627\u0626\u0643\u060c \u0641\u0644\u0645 \u0646\u0632\u0644 \u0628\u0647\u0627 \u062d\u062a\u0649 \u0623\u0630\u0646\u062a\u060c \u0641\u0631\u062c\u0639\u0646\u0627 \u0628\u0647\u060c \u0641\u0623\u0642\u0645\u0646\u0627 \u0623\u0634\u0647\u0631\u064b\u0627 \u062b\u0644\u0627\u062b\u0629 \u0623\u0648 \u0623\u0631\u0628\u0639\u0629.",null)
