B.aT9=new A.a("\u0643\u0627\u0646 \u0628\u0646\u0648 \u0645\u0627\u0644\u0643 \u0648\u0627\u0644\u0623\u062d\u0644\u0627\u0641 -\u0628\u062d\u0643\u0645 \u0623\u0633\u0628\u0642\u064a\u062a\u0647\u0645 \u0627\u0644\u0632\u0645\u0646\u064a\u0629 \u0644\u0644\u0627\u0633\u062a\u064a\u0637\u0627\u0646- \u0647\u0645\u0627 \u0627\u0644\u0645\u0633\u064a\u0637\u0631\u064a\u0646 \u0639\u0644\u064a\u0647\u0627 \u0648\u062a\u0646\u062a\u0647\u064a \u0625\u0644\u064a\u0647\u0645\u0627 \u0642\u064a\u0627\u062f\u062a\u0647\u0627\u060c \u0641\u0643\u0627\u0646\u062a \u0644\u0647\u0645\u0627 \u0627\u0644\u0631\u0626\u0627\u0633\u0629 \u0627\u0644\u062f\u064a\u0646\u064a\u0629 \u0627\u0644\u0645\u062a\u0645\u062b\u0644\u0629 \u0641\u064a \u0631\u0639\u0627\u064a\u0629 \u0627\u0644\u0645\u0633\u062c\u062f\u060c \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0627\u0644\u0632\u0639\u0627\u0645\u0629 \u0627\u0644\u0633\u064a\u0627\u0633\u064a\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0629 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629\u060c \u0648\u0627\u0644\u0646\u0641\u0648\u0630 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f\u064a\u060c \u0625\u0644\u0627 \u0623\u0646\u0647\u0645\u0627 \u0645\u0639 \u0630\u0644\u0643 \u0644\u0645 \u064a\u0643\u0648\u0646\u0627 \u0641\u064a \u0648\u0636\u0639 \u064a\u0645\u0643\u0646\u0647\u0645\u0627 \u0645\u0646 \u0627\u0644\u062f\u0641\u0627\u0639 \u0639\u0646 \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0637\u0627\u0626\u0641\u060c \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u0645\u0646 \u0623\u062e\u0635\u0628 \u0628\u0644\u0627\u062f \u0627\u0644\u0639\u0631\u0628 \u0648\u0623\u0643\u062b\u0631\u0647\u0627 \u062c\u0630\u0628\u064b\u0627 \u0644\u0644\u0623\u0646\u0638\u0627\u0631 \u0648\u0627\u0644\u0623\u0637\u0645\u0627\u0639.",null)
B.aEm=new A.a("\u0641\u0643\u0627\u0646\u0627 \u064a\u062e\u0627\u0641\u0627\u0646 \u0642\u0628\u064a\u0644\u0629 \u0647\u0648\u0627\u0632\u0646\u060c \u0648\u064a\u062e\u0627\u0641\u0627\u0646 \u0642\u0631\u064a\u0634 \u0648\u064a\u062e\u0627\u0641\u0627\u0646 \u0628\u0646\u064a \u0639\u0627\u0645\u0631\u060c \u0648\u0643\u0644\u0647\u0627 \u0642\u0628\u0627\u0626\u0644 \u0642\u0648\u064a\u0629 \u0648\u0642\u0627\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0627\u0646\u0642\u0636\u0627\u0636 \u0648\u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0628\u060c \u0648\u0644\u0630\u0644\u0643 \u0641\u0642\u062f \u0627\u0639\u062a\u0645\u062f \u0632\u0639\u0645\u0627\u0621 \u0627\u0644\u0637\u0627\u0626\u0641 \u0639\u0644\u0649 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0645\u0647\u0627\u062f\u0646\u0629 \u0648\u062d\u0641\u0638 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0631 \u0627\u0644\u0633\u064a\u0627\u0633\u064a \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0639\u0627\u0647\u062f\u0627\u062a \u0648\u0627\u0644\u0645\u0648\u0627\u0632\u0646\u0627\u062a \u0648\u0647\u064a \u0639\u064a\u0646 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u062a\u0633\u064a\u0631 \u0639\u0644\u064a\u0647\u0627 \u0642\u0631\u064a\u0634\u060c \u0641\u0635\u0627\u0631 \u0628\u0646\u0648 \u0645\u0627\u0644\u0643 \u064a\u0648\u062b\u0642\u0648\u0646 \u0639\u0644\u0627\u0642\u0627\u062a\u0647\u0645 \u0645\u0639 \u0647\u0648\u0627\u0632\u0646 \u0644\u064a\u0623\u0645\u0646\u0648\u0627 \u0634\u0631\u0647\u0627\u060c \u0648\u0635\u0627\u0631 \u0627\u0644\u0623\u062d\u0644\u0627\u0641 \u064a\u0631\u062a\u0628\u0637\u0648\u0646 \u0628\u0642\u0631\u064a\u0634 \u0644\u062a\u0623\u0645\u064a\u0646 \u062c\u0627\u0646\u0628\u0647\u0627.",null)
