B.aS3=new A.a("\u0648\u0642\u0627\u0644 \u0627\u0644\u0632\u0647\u0631\u064a \u0641\u064a \u062d\u062f\u064a\u062b\u0647 \u0641\u064a \u0647\u062c\u0631\u0629 \u0627\u0644\u062d\u0628\u0634\u0629: \u0641\u0644\u0645\u0627 \u0643\u062b\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646\u060c \u0648\u0638\u0647\u0631 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u064f\u062a\u062d\u062f\u062b \u0628\u0647\u060c \u062b\u0627\u0631 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0645\u0646 \u0643\u0641\u0627\u0631 \u0642\u0631\u064a\u0634 \u0628\u0645\u0646 \u0622\u0645\u0646 \u0645\u0646 \u0642\u0628\u0627\u0626\u0644\u0647\u0645 \u064a\u0639\u0630\u0628\u0648\u0646\u0647\u0645 \u0648\u064a\u0633\u062c\u0646\u0648\u0646\u0647\u0645 \u0648\u0623\u0631\u0627\u062f\u0648\u0627 \u0641\u062a\u0646\u062a\u0647\u0645 \u0639\u0646 \u062f\u064a\u0646\u0647\u0645 \u0641\u0644\u0645\u0627 \u0628\u0644\u063a \u0630\u0644\u0643 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u0627\u0644 \u0644\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0647: \u062a\u0641\u0631\u0642\u0648\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0642\u0627\u0644\u0648\u0627: \u0641\u0623\u064a\u0646 \u0646\u0630\u0647\u0628 \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0642\u0627\u0644: \u0647\u0627\u0647\u0646\u0627 \u0648\u0623\u0634\u0627\u0631 \u0625\u0644\u0649 \u0623\u0631\u0636 \u0627\u0644\u062d\u0628\u0634\u0629.",null)
B.atP=new A.a("\u0648\u0643\u0627\u0646\u062a \u0627\u0644\u062e\u0637\u0629 \u0627\u0644\u0623\u0645\u0646\u064a\u0629 \u0644\u0644\u0631\u0633\u0648\u0644 \ufdfa \u062a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0635\u0641\u0648\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u0629\u060c \u0648\u0644\u0630\u0644\u0643 \u0631\u0623\u0649 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0623\u0646 \u0627\u0644\u062d\u0628\u0634\u0629 \u062a\u0639\u062a\u0628\u0631 \u0645\u0643\u0627\u0646\u064b\u0627 \u0622\u0645\u0646\u064b\u0627 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0631\u064a\u062b\u0645\u0627 \u064a\u0634\u062a\u062f \u0639\u0648\u062f \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u062a\u0647\u062f\u0623 \u0627\u0644\u0639\u0627\u0635\u0641\u0629\u060c \u0648\u0642\u062f \u0648\u062c\u062f \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0648\u0646 \u0641\u064a \u0623\u0631\u0636 \u0627\u0644\u062d\u0628\u0634\u0629 \u0645\u0627 \u0623\u0645\u0646\u0647\u0645 \u0648\u0637\u0645\u0623\u0646\u0647\u0645\u060c \u0648\u0641\u064a \u0630\u0644\u0643 \u062a\u0642\u0648\u0644 \u0623\u0645 \u0633\u0644\u0645\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627: \u0644\u0645\u0627 \u0646\u0632\u0644\u0646\u0627 \u0623\u0631\u0636 \u0627\u0644\u062d\u0628\u0634\u0629 \u062c\u0627\u0648\u0631\u0646\u0627 \u0628\u0647\u0627 \u062e\u064a\u0631 \u062c\u0627\u0631 \u0627\u0644\u0646\u062c\u0627\u0634\u064a\u060c \u0623\u064e\u0645\u0650\u0646\u0651\u064e\u0627 \u0639\u0644\u0649 \u062f\u064a\u0646\u0646\u0627 \u0648\u0639\u0628\u062f\u0646\u0627 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u0646\u0624\u0630\u0649... .",null)
