B.aUH=new A.a("\u0641\u0642\u0627\u0644 \u0643\u0639\u0628 \u0628\u0646 \u0645\u0627\u0644\u0643: \u0641\u0644\u0645\u0627 \u0628\u0644\u063a\u0646\u064a \u0623\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u062f \u062a\u0648\u062c\u0647 \u0642\u0627\u0641\u0644\u0627\u064b \u0645\u0646 \u062a\u0628\u0648\u0643 \u062d\u0636\u0631\u0646\u064a \u0628\u062b\u064a -\u062d\u0632\u0646\u064a- \u0641\u0637\u0641\u0642\u062a \u0623\u062a\u0630\u0643\u0631 \u0627\u0644\u0643\u0630\u0628 \u0648\u0623\u0642\u0648\u0644: \u0628\u0645 \u0623\u062e\u0631\u062c \u0645\u0646 \u0633\u062e\u0637\u0647 \u063a\u062f\u0627\u064b\u061f \u0648\u0623\u0633\u062a\u0639\u064a\u0646 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0643\u0644 \u0630\u064a \u0631\u0623\u064a \u0645\u0646 \u0623\u0647\u0644\u064a\u060c \u0641\u0644\u0645\u0627 \u0642\u064a\u0644 \u0644\u064a: \u0623\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u062f \u0623\u0638\u0644 \u0642\u0627\u062f\u0645\u0627\u064b -\u0623\u0642\u0628\u0644 \u0648\u062f\u0646\u0627 \u0642\u062f\u0648\u0645\u0647 \u0643\u0623\u0646\u0647 \u0623\u0628\u0642\u0649 \u0639\u0644\u0649 \u0638\u0644\u0647- \u0632\u0627\u062d \u0639\u0646\u064a \u0627\u0644\u0628\u0627\u0637\u0644 \u062d\u062a\u0649 \u0639\u0631\u0641\u062a \u0623\u0646\u064a \u0644\u0646 \u0623\u0646\u062c\u0648 \u0645\u0646\u0647 \u0628\u0634\u064a\u0621 \u0623\u0628\u062f\u0627\u064b\u060c \u0641\u0623\u062c\u0645\u0639\u062a \u0635\u062f\u0642\u0647 -\u0639\u0632\u0645\u062a \u0639\u0644\u0649 \u0635\u062f\u0642\u0647- \u0648\u0635\u0628\u062d \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u0627\u062f\u0645\u0627\u064b\u060c \u0648\u0643\u0627\u0646 \u0625\u0630\u0627 \u0642\u062f\u0645 \u0645\u0646 \u0633\u0641\u0631 \u0628\u062f\u0623 \u0628\u0627\u0644\u0645\u0633\u062c\u062f \u0641\u0631\u0643\u0639 \u0641\u064a\u0647 \u0631\u0643\u0639\u062a\u064a\u0646 \u062b\u0645 \u062c\u0644\u0633 \u0644\u0644\u0646\u0627\u0633\u060c \u0641\u0644\u0645\u0627 \u0641\u0639\u0644 \u0630\u0644\u0643 \u062c\u0627\u0621\u0647 \u0627\u0644\u0645\u062e\u0644\u0641\u0648\u0646 \u0641\u0637\u0641\u0642\u0648\u0627 \u064a\u0639\u062a\u0630\u0631\u0648\u0646 \u0625\u0644\u064a\u0647 \u0648\u064a\u062d\u0644\u0641\u0648\u0646 \u0644\u0647 \u0648\u0643\u0627\u0646\u0648\u0627 \u0628\u0636\u0639\u0629 \u0648\u062b\u0645\u0627\u0646\u064a\u0646 \u0631\u062c\u0644\u0627\u064b\u060c \u0641\u0642\u0628\u0644 \u0645\u0646\u0647\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0644\u0627\u0646\u064a\u062a\u0647\u0645 \u0648\u0628\u0627\u064a\u0639\u0647\u0645 \u0648\u0627\u0633\u062a\u063a\u0641\u0631 \u0644\u0647\u0645 \u0648\u0648\u0643\u0644 \u0633\u0631\u0627\u0626\u0631\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u062d\u062a\u0649 \u062c\u0626\u062a \u0641\u0644\u0645\u0627 \u0633\u0644\u0645\u062a \u062a\u0628\u0633\u0645 \u062a\u0628\u0633\u0645 \u0627\u0644\u0645\u063a\u0636\u0628 \u062b\u0645 \u0642\u0627\u0644: \u062a\u0639\u0627\u0644 \u0641\u062c\u0626\u062a \u0623\u0645\u0634\u064a \u062d\u062a\u0649 \u062c\u0644\u0633\u062a \u0628\u064a\u0646 \u064a\u062f\u064a\u0647\u060c \u0641\u0642\u0627\u0644 \u0644\u064a: \u0645\u0627\u062e\u0644\u0641\u0643\u061f \u0623\u0644\u0645 \u062a\u0643\u0646 \u0642\u062f \u0627\u0628\u062a\u0639\u062a \u0638\u0647\u0631\u0643\u061f \u0642\u0627\u0644: \u0642\u0644\u062a: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647! \u0625\u0646\u064a \u0648\u0627\u0644\u0644\u0647 \u0644\u0648 \u062c\u0644\u0633\u062a \u0639\u0646\u062f \u063a\u064a\u0631\u0643 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u062f\u0646\u064a\u0627 \u0644\u0631\u0623\u064a\u062a \u0623\u0646\u064a \u0633\u0623\u062e\u0631\u062c \u0645\u0646 \u0633\u062e\u0637\u0647 \u0628\u0639\u0630\u0631 \u0648\u0644\u0642\u062f \u0623\u0639\u0637\u064a\u062a \u062c\u062f\u0644\u0627\u064b -\u0641\u0635\u0627\u062d\u0629 \u0648\u0642\u0648\u0629 \u0641\u064a \u0627\u0644\u0643\u0644\u0627\u0645 \u0648\u0628\u0631\u0627\u0639\u0629- \u060c \u0648\u0644\u0643\u0646\u064a \u0648\u0627\u0644\u0644\u0647! \u0644\u0642\u062f \u0639\u0644\u0645\u062a \u0644\u0626\u0646 \u062d\u062f\u062b\u062a\u0643 \u0627\u0644\u064a\u0648\u0645 \u062d\u062f\u064a\u062b \u0643\u0630\u0628 \u062a\u0631\u0636\u0649 \u0628\u0647 \u0639\u0646\u064a\u060c \u0644\u064a\u0648\u0634\u0643\u0646 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0633\u062e\u0637\u0643 \u0639\u0644\u064a\u0651 \u0648\u0644\u0626\u0646 \u062d\u062f\u062b\u062a\u0643 \u062d\u062f\u064a\u062b \u0635\u062f\u0642 \u062a\u062c\u062f \u0639\u0644\u064a \u0641\u064a\u0647 -\u062a\u063a\u0636\u0628- \u0625\u0646\u064a \u0644\u0623\u0631\u062c\u0648 \u0641\u064a\u0647 \u0639\u0642\u0628\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0643\u0627\u0646 \u0644\u064a \u0639\u0630\u0631 \u0648\u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0643\u0646\u062a \u0642\u0637 \u0623\u0642\u0648\u0649 \u0648\u0644\u0627 \u0623\u064a\u0633\u0631 \u0645\u0646\u064a \u062d\u064a\u0646 \u062a\u062e\u0644\u0641\u062a \u0639\u0646\u0643\u060c \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0623\u0645\u0627 \u0647\u0630\u0627 \u0641\u0642\u062f \u0635\u062f\u0642 \u0641\u0642\u0645 \u062d\u062a\u0649 \u064a\u0642\u0636\u064a \u0627\u0644\u0644\u0647 \u0641\u064a\u0643\u060c \u0641\u0642\u0645\u062a \u0648\u062b\u0627\u0631 \u0631\u062c\u0627\u0644 \u0645\u0646 \u0628\u0646\u064a \u0633\u0644\u0645\u0629 \u0641\u0627\u062a\u0628\u0639\u0648\u0646\u064a\u060c \u0641\u0642\u0627\u0644\u0648\u0627 \u0644\u064a: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0639\u0644\u0645\u0646\u0627\u0643 \u0623\u0630\u0646\u0628\u062a \u0630\u0646\u0628\u0627\u064b \u0642\u0628\u0644 \u0647\u0630\u0627\u060c \u0644\u0642\u062f \u0639\u062c\u0632\u062a \u0641\u064a \u0623\u0646 \u0644\u0627\u062a\u0643\u0648\u0646 \u0627\u0639\u062a\u0630\u0631\u062a \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0645\u0627 \u0627\u0639\u062a\u0630\u0631 \u0628\u0647 \u0625\u0644\u064a\u0647 \u0627\u0644\u0645\u062e\u0644\u0641\u0648\u0646\u060c \u0641\u0642\u062f \u0643\u0627\u0646 \u0643\u0627\u0641\u064a\u0643 \u0630\u0646\u0628\u0643 \u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0643\u060c \u0642\u0627\u0644 \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0632\u0627\u0644\u0648\u0627 \u064a\u0624\u0646\u0628\u0648\u0646\u0646\u064a -\u064a\u0644\u0648\u0645\u0646\u0646\u064a \u0627\u0634\u062f \u0627\u0644\u0644\u0648\u0645- \u062d\u062a\u0649 \u0623\u0631\u062f\u062a \u0623\u0646 \u0623\u0631\u062c\u0639 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0623\u0643\u0630\u0628 \u0646\u0641\u0633\u064a.",null)
B.aBM=new A.a("\u0642\u0627\u0644: \u062b\u0645 \u0642\u0644\u062a \u0644\u0647\u0645: \u0647\u0644 \u0644\u0642\u064a \u0647\u0630\u0627 \u0645\u0639\u064a \u0645\u0646 \u0623\u062d\u062f\u061f \u0642\u0627\u0644\u0648\u0627: \u0646\u0639\u0645\u060c \u0644\u0642\u064a\u0647 \u0645\u0639\u0643 \u0631\u062c\u0644\u0627\u0646 \u0642\u0627\u0644\u0627 \u0645\u062b\u0644 \u0645\u0627\u0642\u0644\u062a \u0641\u0642\u064a\u0644 \u0644\u0647\u0645\u0627 \u0645\u062b\u0644 \u0645\u0627\u0642\u064a\u0644 \u0644\u0643\u060c \u0642\u0627\u0644: \u0642\u0644\u062a: \u0645\u0646 \u0647\u0645\u0627\u061f \u0642\u0627\u0644\u0648\u0627: \u0645\u0631\u0627\u0631\u0629 \u0628\u0646 \u0627\u0644\u0631\u0628\u064a\u0639 \u0627\u0644\u0639\u0627\u0645\u0631\u064a \u0648\u0647\u0644\u0627\u0644 \u0628\u0646 \u0623\u0645\u064a\u0629 \u0627\u0644\u0648\u0627\u0642\u0641\u064a\u060c \u0642\u0627\u0644: \u0641\u0630\u0643\u0631\u0648\u0627 \u0644\u064a \u0631\u062c\u0644\u064a\u0646 \u0635\u0627\u0644\u062d\u064a\u0646 \u0642\u062f \u0634\u0647\u062f\u0648\u0627 \u0628\u062f\u0631\u0627\u064b \u0641\u064a\u0647\u0645\u0627 \u0623\u0633\u0648\u0629\u060c \u0641\u0645\u0636\u064a\u062a \u062d\u064a\u0646 \u0630\u0643\u0631\u0648\u0647\u0645\u0627 \u0644\u064a.",null)
