B.aPC=new A.a("\u062b\u0645 \u0642\u0631\u0631 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u062d\u0642\u064a\u0642\u0629 \u0642\u0627\u0626\u0645\u0629 \u0641\u064a \u0646\u0641\u0648\u0633 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u0644\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0631\u064e\u0647\u0652\u0628\u064e\u0629\u064b \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650\u0647\u0650\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0630\u064e\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u060c\u0623\u064a \u0644\u0623\u0646\u062a\u0645 \u064a\u0627\u0645\u0639\u0634\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0623\u0634\u062f \u062e\u0648\u0641\u0627\u064b \u0648\u062e\u0634\u064a\u0629 \u0641\u064a \u0635\u062f\u0648\u0631 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0641\u0647\u0645 \u064a\u062e\u0627\u0641\u0648\u0646\u0643\u0645 \u0623\u0643\u062b\u0631 \u0645\u0646 \u062e\u0648\u0641\u0647\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0647\u0630\u0647 \u0627\u0644\u062d\u0627\u0644 \u0645\u0646\u0647\u0645 \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u0627 \u064a\u064e\u0641\u0652\u0642\u064e\u0647\u064f\u0648\u0646\u064e \u0627\u064a \u0644\u0627\u064a\u0639\u0644\u0645\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u0639\u0638\u0645\u062a\u0647 \u062d\u062a\u0649 \u064a\u062e\u0634\u0648\u0647 \u062d\u0642 \u062e\u0634\u064a\u062a\u0647 \u062b\u0645 \u0623\u0643\u062f \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u062d\u0642\u064a\u0642\u0629 \u0628\u0635\u0641\u0627\u062a \u0623\u062e\u0631\u0649 \u0641\u064a\u0647\u0645\u060c \u0641\u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u0644\u0627 \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0625\u0650\u0644\u0627 \u0641\u0650\u064a \u0642\u064f\u0631\u064b\u0649 \u0645\u064f\u062d\u064e\u0635\u0651\u064e\u0646\u064e\u0629\u064d \u0623\u064e\u0648\u0652 \u0645\u0650\u0646\u0652 \u0648\u064e\u0631\u064e\u0627\u0621\u0650 \u062c\u064f\u062f\u064f\u0631\u064d \u060c\u0641\u0642\u062f \u0643\u0634\u0641 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0639\u0646 \u062d\u0642\u0627\u0626\u0642 \u0646\u0641\u0633\u064a\u0629 \u0627\u0644\u064a\u0647\u0648\u062f \u0641\u0647\u0645 \u062c\u0628\u0646\u0627\u0621 \u0644\u0627\u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0623\u0646 \u064a\u0648\u0627\u062c\u0647\u0648\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u0637\u0646 \u0645\u0643\u0634\u0648\u0641\u0629 \u0628\u0644 \u0644\u0627 \u064a\u0642\u0627\u062a\u0644\u0648\u0646 \u0625\u0644\u0627 \u0645\u0646 \u0648\u0631\u0627\u0621 \u0642\u0631\u0627\u0647\u0645 \u0627\u0644\u0645\u062d\u0635\u0646\u0629 \u0628\u0627\u0644\u062e\u0646\u0627\u062f\u0642 \u0648\u062c\u062f\u0631\u0627\u0646\u0647\u0645 \u0648\u062d\u0648\u0627\u0626\u0637\u0647\u0645 \u0627\u0644\u062a\u064a \u064a\u062a\u0633\u062a\u0631\u0648\u0646 \u0645\u0646 \u062e\u0644\u0641\u0647\u0627.",null)
B.aGM=new A.a("\u062b\u0645 \u0643\u0634\u0641 \u0627\u0644\u0642\u0631\u0622\u0646 \u0639\u0646 \u0628\u0639\u0636 \u0623\u0633\u0628\u0627\u0628 \u0636\u0639\u0641\u0647\u0645 \u0648\u062e\u0648\u0631\u0647\u0645 \u0641\u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u0628\u064e\u0623\u0652\u0633\u064f\u0647\u064f\u0645\u0652 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0634\u064e\u062f\u0650\u064a\u062f\u064c \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064f\u0647\u064f\u0645\u0652 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0648\u064e\u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0634\u064e\u062a\u0651\u064e\u0649 \u0630\u064e\u0644\u0650\u0643\u064e \u0628\u0650\u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0642\u064e\u0648\u0652\u0645\u064c \u0644\u0627 \u064a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e \u060c \u0641\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0641\u064a \u0627\u0644\u0638\u0627\u0647\u0631 \u062a\u0631\u0627\u0647\u0645 \u0645\u062c\u062a\u0645\u0639\u064a\u0646 \u0635\u0641\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0636\u062f \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0644\u0643\u0646 \u0627\u0644\u0622\u064a\u0629 \u062a\u0628\u064a\u0646 \u0623\u0646\u0647\u0645 \u0639\u0643\u0633 \u0630\u0644\u0643 \u0641\u064a \u0627\u0644\u062d\u0642\u064a\u0642\u0629 \u0641\u0647\u0645 \u0628\u0623\u0633\u0647\u0645 \u0628\u064a\u0646\u0647\u0645 \u0634\u062f\u064a\u062f\u060c \u0623\u064a: \u0639\u062f\u0627\u0648\u062a\u0647\u0645 \u0628\u0639\u0636\u0647\u0645 \u0644\u0628\u0639\u0636 \u0634\u062f\u064a\u062f\u0629 \u062a\u062d\u0633\u0628\u0647\u0645 \u062c\u0645\u064a\u0639\u0627\u064b \u0623\u064a: \u062a\u0638\u0646\u0647\u0645 \u0645\u062c\u062a\u0645\u0639\u064a\u0646 \u0639\u0644\u0649 \u0623\u0645\u0631 \u0648\u0631\u0623\u064a \u0648\u0644\u0643\u0646\u0647\u0645 \u0641\u064a \u0627\u0644\u062d\u0642\u064a\u0642\u0629 \u0642\u0644\u0648\u0628\u0647\u0645 \u0634\u062a\u0649 \u0623\u064a \u0645\u062a\u0641\u0631\u0642\u0629.",null)
